import faiss
import numpy as np

index = faiss.IndexFlatIP({{dim}})

def add(vectors: np.ndarray):
    index.add(vectors.astype("float32"))

def search(query: np.ndarray, k: int = 5):
    D, I = index.search(query.astype("float32"), k)
    return D, I

def save():
    faiss.write_index(index, "{{index_path}}")

if __name__ == "__main__":
    add(np.random.rand(100, {{dim}}))
    save()
